# Linker version script for the TEST-ONLY instrumented hook DSO.
#
# Same strict export policy as the shipped library (OnLoad/OnUnload only), plus
# the rj_test_* entry points the unit tests link against. This DSO is never
# installed, so exporting the test hooks here keeps the shipped ABI clean while
# still letting tests drive internal state. Keep this list in sync with the
# RJ_HOOK_TEST_HOOKS entry points in rj_hsa_dbt_hooks.cpp.
{
  global:
    OnLoad;
    OnUnload;
    rj_test_*;
  local:
    *;
};
